# Method overriding — replacing parent methods

print("=== Basic method overriding ===\n")

class Animal:
    def __init__(self, name):
        self.name = name

    def speak(self):
        return "Some generic sound"

    def move(self):
        return "Moves somehow"

class Dog(Animal):
    def speak(self):
        return "Woof!"

    def move(self):
        return "Runs on four legs"

class Cat(Animal):
    def speak(self):
        return "Meow!"

    def move(self):
        return "Pounces gracefully"

# Using overridden methods
animals = [
    Dog("Rex"),
    Cat("Whiskers"),
    Animal("Unknown")
]

for animal in animals:
    print(f"{animal.name}: {animal.speak()} - {animal.move()}")

print("\n=== Overriding with super() ===\n")

class Character:
    def __init__(self, name, level):
        self.name = name
        self.level = level
        self.health = 100

    def display(self):
        return f"Name: {self.name}, Level: {self.level}, HP: {self.health}"

    def attack(self):
        return self.level * 5

class Warrior(Character):
    def __init__(self, name, level, weapon):
        super().__init__(name, level)
        self.weapon = weapon
        self.health = 150  # Override health

    def display(self):
        # Call parent display and add weapon
        base = super().display()
        return f"{base}, Weapon: {self.weapon}"

    def attack(self):
        # Call parent attack and add weapon bonus
        base = super().attack()
        return base + 20

class Mage(Character):
    def __init__(self, name, level, spell):
        super().__init__(name, level)
        self.spell = spell
        self.mana = 100

    def display(self):
        base = super().display()
        return f"{base}, Spell: {self.spell}, Mana: {self.mana}"

    def attack(self):
        base = super().attack()
        return base + 15

# Create instances
aragorn = Warrior("Aragorn", 15, "Andúril")
gandalf = Mage("Gandalf", 50, "Fireball")

print(aragorn.display())
print(f"Attack: {aragorn.attack()}")
print()
print(gandalf.display())
print(f"Attack: {gandalf.attack()}")

print("\n=== Overriding __str__ ===\n")

class Player:
    def __init__(self, name, level):
        self.name = name
        self.level = level

    def __str__(self):
        return f"Player: {self.name} (Level {self.level})"

    def __repr__(self):
        return f"Player('{self.name}', {self.level})"

hero = Player("Aragorn", 15)
print(str(hero))
print(repr(hero))

