phase3.solution:
class Item:
    def __init__(self, name, value):
        self.name = name
        self.value = value

    def __str__(self):
        return f"Item: {self.name} ({self.value})"

    def __repr__(self):
        return f"Item('{self.name}', {self.value})"

    def use(self):
        return f"Using {self.name}"

class Weapon(Item):
    def __init__(self, name, value, damage):
        super().__init__(name, value)
        self.damage = damage

    def __str__(self):
        return f"{super().__str__()} - Damage: {self.damage}"

    def __repr__(self):
        return f"Weapon('{self.name}', {self.value}, {self.damage})"

    def use(self):
        return f"Attacking with {self.name} for {self.damage} damage!"

class Potion(Item):
    def __init__(self, name, value, effect):
        super().__init__(name, value)
        self.effect = effect

    def __str__(self):
        return f"{super().__str__()} - Effect: {self.effect}"

    def __repr__(self):
        return f"Potion('{self.name}', {self.value}, '{self.effect}')"

    def use(self):
        return f"Drinking {self.name}: {self.effect}"

# Create items
sword = Item("Sword", 50)
magic_sword = Weapon("Magic Sword", 200, 30)
potion = Potion("Health Potion", 25, "Heals 50 HP")

# Display
print(str(sword))
print(f"Repr: {repr(sword)}")
print(f"Use: {sword.use()}")
print()

print(str(magic_sword))
print(f"Repr: {repr(magic_sword)}")
print(f"Use: {magic_sword.use()}")
print()

print(str(potion))
print(f"Repr: {repr(potion)}")
print(f"Use: {potion.use()}")
